/**
 * Calendar arithmetic for recurring issues.
 *
 * Occurrences are calendar days (`YYYY-MM-DD`) in a rule's own IANA time zone,
 * and day D "has started" once the local wall clock in that zone has reached
 * 00:00 on D. Everything zone-dependent goes through `Intl`, so daylight-saving
 * transitions — including zones whose midnight is skipped or repeated — follow
 * the runtime's tz database. Pure and client-safe: `src/schemas` imports the
 * validators.
 */
import type { RecurrenceCadence } from "@/types/recurring-issue";

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

const SECOND_MS = 1_000;
const HOUR_MS = 60 * 60 * SECOND_MS;

/** Wider than any UTC offset the tz database has ever used. */
const SEARCH_WINDOW_MS = 27 * HOUR_MS;

const formatters = new Map<string, Intl.DateTimeFormat>();

function formatterFor(timeZone: string): Intl.DateTimeFormat {
  let formatter = formatters.get(timeZone);
  if (formatter === undefined) {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      era: "short",
      year: "numeric",
      month: "numeric",
      day: "numeric",
      hour: "numeric",
      minute: "numeric",
      second: "numeric",
    });
    formatters.set(timeZone, formatter);
  }
  return formatter;
}

/**
 * True for a time zone name the runtime's tz database knows, e.g.
 * `"Europe/Berlin"` or `"UTC"`. Raw UTC offsets such as `"+02:00"` are
 * accepted by newer `Intl` builds but are not IANA zones, so they are refused.
 */
export function isIanaTimeZone(value: string): boolean {
  if (value.trim() !== value || value.length === 0) return false;
  if (/^[+\-−]/.test(value)) return false;
  try {
    formatterFor(value);
    return true;
  } catch {
    return false;
  }
}

function parseCalendarDate(
  value: string,
): { year: number; month: number; day: number } | null {
  const match = CALENDAR_DATE.exec(value);
  if (!match) return null;
  return { year: Number(match[1]), month: Number(match[2]), day: Number(match[3]) };
}

/** Milliseconds of `00:00` on a calendar date, read as if it were UTC. */
function utcMidnight(year: number, month: number, day: number): number {
  // `setUTCFullYear` rather than `Date.UTC`, which maps years 0–99 to 19xx.
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  return date.getTime();
}

function formatCalendarDate(ms: number): string {
  const date = new Date(ms);
  const year = String(date.getUTCFullYear()).padStart(4, "0");
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function requireCalendarDate(value: string): number {
  const parts = parseCalendarDate(value);
  if (parts === null || !isCalendarDate(value)) {
    throw new RangeError(`Not a YYYY-MM-DD calendar date: "${value}"`);
  }
  return utcMidnight(parts.year, parts.month, parts.day);
}

/** True for a `YYYY-MM-DD` string naming a day that exists (no `2026-02-30`). */
export function isCalendarDate(value: string): boolean {
  const parts = parseCalendarDate(value);
  if (parts === null) return false;
  if (parts.month < 1 || parts.month > 12 || parts.day < 1) return false;
  return formatCalendarDate(utcMidnight(parts.year, parts.month, parts.day)) === value;
}

/** `date` shifted by `days` calendar days. */
export function addCalendarDays(date: string, days: number): string {
  const midnight = requireCalendarDate(date);
  const shifted = new Date(midnight);
  shifted.setUTCDate(shifted.getUTCDate() + days);
  return formatCalendarDate(shifted.getTime());
}

/** ISO weekday of a calendar date: 1 = Monday … 7 = Sunday. */
export function isoWeekday(date: string): number {
  const day = new Date(requireCalendarDate(date)).getUTCDay();
  return day === 0 ? 7 : day;
}

/**
 * The wall-clock reading in `timeZone` at `instantMs`, expressed as
 * milliseconds of the same reading taken as UTC. Second precision — the tz
 * database never changes offset mid-second.
 */
function wallClockMs(instantMs: number, timeZone: string): number {
  const at = Math.floor(instantMs / SECOND_MS) * SECOND_MS;
  const fields: Record<string, string> = {};
  for (const part of formatterFor(timeZone).formatToParts(new Date(at))) {
    fields[part.type] = part.value;
  }

  const rawYear = Number(fields.year);
  const year = fields.era === "BC" || fields.era === "B" ? 1 - rawYear : rawYear;

  const date = new Date(0);
  date.setUTCFullYear(year, Number(fields.month) - 1, Number(fields.day));
  date.setUTCHours(
    Number(fields.hour),
    Number(fields.minute),
    Number(fields.second),
    0,
  );
  return date.getTime();
}

function offsetMs(instantMs: number, timeZone: string): number {
  const at = Math.floor(instantMs / SECOND_MS) * SECOND_MS;
  return wallClockMs(at, timeZone) - at;
}

/** The calendar date the wall clock in `timeZone` shows at `instant`. */
export function localDateAt(instant: Date, timeZone: string): string {
  return formatCalendarDate(wallClockMs(instant.getTime(), timeZone)).slice(0, 10);
}

/** First second in `(fromMs, toMs]` whose offset differs from `fromMs`'s. */
function findTransition(fromMs: number, toMs: number, timeZone: string): number {
  const before = offsetMs(fromMs, timeZone);
  let low = fromMs;
  let high = toMs;
  while (high - low > SECOND_MS) {
    const mid = low + Math.floor((high - low) / 2 / SECOND_MS) * SECOND_MS;
    if (offsetMs(mid, timeZone) === before) {
      low = mid;
    } else {
      high = mid;
    }
  }
  return high;
}

/**
 * The first instant at which the wall clock in `timeZone` reads `date` 00:00
 * or later. When midnight is skipped by a DST jump that is the jump itself;
 * when it is repeated, the earlier of the two.
 */
export function startOfLocalDay(date: string, timeZone: string): Date {
  const target = requireCalendarDate(date);
  const windowStart = target - SEARCH_WINDOW_MS;
  const windowEnd = target + SEARCH_WINDOW_MS;

  // Split the window into constant-offset segments. Offsets change at most a
  // couple of times a year, so an hourly probe cannot step over two changes.
  const segments: { start: number; end: number; offset: number }[] = [];
  let segmentStart = windowStart;
  let segmentOffset = offsetMs(windowStart, timeZone);

  for (let probe = windowStart + HOUR_MS; probe <= windowEnd; probe += HOUR_MS) {
    const offset = offsetMs(probe, timeZone);
    if (offset === segmentOffset) continue;

    const transition = findTransition(probe - HOUR_MS, probe, timeZone);
    segments.push({ start: segmentStart, end: transition, offset: segmentOffset });
    segmentStart = transition;
    segmentOffset = offsetMs(transition, timeZone);
  }
  segments.push({ start: segmentStart, end: Number.POSITIVE_INFINITY, offset: segmentOffset });

  for (const segment of segments) {
    const candidate = Math.max(segment.start, target - segment.offset);
    if (candidate < segment.end) return new Date(candidate);
  }

  // Unreachable: the last segment is open-ended.
  return new Date(target);
}

/** The latest calendar day in `timeZone` that has started by `now`. */
export function latestStartedDay(now: Date, timeZone: string): string {
  const shown = localDateAt(now, timeZone);

  // A clock set back across midnight can show yesterday's date after today
  // has already begun; a started day stays started.
  const next = addCalendarDays(shown, 1);
  if (startOfLocalDay(next, timeZone).getTime() <= now.getTime()) return next;

  if (startOfLocalDay(shown, timeZone).getTime() <= now.getTime()) return shown;
  return addCalendarDays(shown, -1);
}

export interface RecurrenceSpec {
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
}

/**
 * The latest occurrence of `rule` that has started by `now`, or `null` when
 * none has. Daily rules occur on every day from `startsOn`; weekly rules on
 * every such day whose ISO weekday is `weekday`.
 */
export function latestOccurrence(rule: RecurrenceSpec, now: Date): string | null {
  const today = latestStartedDay(now, rule.timezone);

  let occurrence = today;
  if (rule.cadence === "weekly") {
    if (rule.weekday === null) return null;
    const back = (isoWeekday(today) - rule.weekday + 7) % 7;
    occurrence = addCalendarDays(today, -back);
  }

  return occurrence >= rule.startsOn ? occurrence : null;
}

