 * The first instant at which the wall clock in `timeZone` reads `date` 00:00
 * or later. When midnight is skipped by a DST jump that is the jump itself;
 * when it is repeated, the earlier of the two.
 */
export function startOfLocalDay(date: string, timeZone: string): Date {
  const target = requireCalendarDate(date);
  const windowStart = target - SEARCH_WINDOW_MS;
  const windowEnd = target + SEARCH_WINDOW_MS;

  // Split the window into constant-offset segments. Offsets change at most a
  // couple of times a year, so an hourly probe cannot step over two changes.
  const segments: { start: number; end: number; offset: number }[] = [];
  let segmentStart = windowStart;
  let segmentOffset = offsetMs(windowStart, timeZone);

  for (let probe = windowStart + HOUR_MS; probe <= windowEnd; probe += HOUR_MS) {
    const offset = offsetMs(probe, timeZone);
    if (offset === segmentOffset) continue;

    const transition = findTransition(probe - HOUR_MS, probe, timeZone);
    segments.push({ start: segmentStart, end: transition, offset: segmentOffset });
    segmentStart = transition;
    segmentOffset = offsetMs(transition, timeZone);
  }
  segments.push({ start: segmentStart, end: Number.POSITIVE_INFINITY, offset: segmentOffset });

  for (const segment of segments) {
    const candidate = Math.max(segment.start, target - segment.offset);
    if (candidate < segment.end) return new Date(candidate);
  }

  // Unreachable: the last segment is open-ended.
  return new Date(target);
}

/** The latest calendar day in `timeZone` that has started by `now`. */
export function latestStartedDay(now: Date, timeZone: string): string {
  const shown = localDateAt(now, timeZone);

  // A clock set back across midnight can show yesterday's date after today
  // has already begun; a started day stays started.
  const next = addCalendarDays(shown, 1);
  if (startOfLocalDay(next, timeZone).getTime() <= now.getTime()) return next;

  if (startOfLocalDay(shown, timeZone).getTime() <= now.getTime()) return shown;
  return addCalendarDays(shown, -1);
}

export interface RecurrenceSpec {
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
}

/**
 * The latest occurrence of `rule` that has started by `now`, or `null` when
 * none has. Daily rules occur on every day from `startsOn`; weekly rules on
 * every such day whose ISO weekday is `weekday`.
 */
export function latestOccurrence(rule: RecurrenceSpec, now: Date): string | null {
  const today = latestStartedDay(now, rule.timezone);

  let occurrence = today;
  if (rule.cadence === "weekly") {
    if (rule.weekday === null) return null;
    const back = (isoWeekday(today) - rule.weekday + 7) % 7;
    occurrence = addCalendarDays(today, -back);
  }

  return occurrence >= rule.startsOn ? occurrence : null;
}

