import { z } from "zod";
import { isCalendarDate, isIanaTimeZone } from "@/lib/recurrence";
import type { RecurrenceCadence } from "@/types/recurring-issue";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";
import { issuePrioritySchema } from "./issue";

export const recurrenceCadenceSchema = z.enum(["daily", "weekly"]);

/** ISO weekday: 1 = Monday … 7 = Sunday. */
export const isoWeekdaySchema = z.number().int().min(1).max(7);

/** A `YYYY-MM-DD` day that actually exists on the calendar. */
export const calendarDateSchema = z
  .string()
  .refine(isCalendarDate, "must be a real YYYY-MM-DD date");

/** An IANA time zone name the runtime knows, e.g. `Europe/Berlin`. */
export const timeZoneSchema = z
  .string()
  .refine(isIanaTimeZone, "must be a known IANA time zone");

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3, "give the recurring issue a title").max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: recurrenceCadenceSchema,
    weekday: isoWeekdaySchema.nullable().default(null),
    timezone: timeZoneSchema,
    startsOn: calendarDateSchema,
  })
  .superRefine((value, ctx) => {
    if (value.cadence === "weekly" && value.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "a weekly rule needs a weekday",
      });
    }
    if (value.cadence === "daily" && value.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "a daily rule has no weekday",
      });
    }
  });

const _cadenceParity: RecurrenceCadence = "weekly" satisfies z.infer<
  typeof recurrenceCadenceSchema
>;
void _cadenceParity;

export type CreateRecurringIssueInput = z.input<typeof createRecurringIssueSchema>;
export type ParsedCreateRecurringIssueInput = z.output<
  typeof createRecurringIssueSchema
>;

