/**
 * Files the latest due occurrence of every non-paused recurring-issue rule as an ordinary issue.
 *
 * Must call (do not reimplement): can, isArchived, latestOccurrence, createIssue
 */
import { createLogger } from "@/lib/logger";
import { can } from "@/lib/permissions";
import { latestOccurrence } from "@/lib/recurrence";
import { isArchived } from "@/lib/soft-delete";
import { createIssueSchema } from "@/schemas/issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

type RuleOutcome = "created" | "skipped" | "paused" | "refused";

/**
 * One pass over every live rule. Missed occurrences are never back-filled: a
 * rule files at most one issue per run, for the latest occurrence that has
 * started, and `lastOccurrenceOn` makes a second run for the same `now` a
 * no-op. `processed` counts the issues created.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listUnpausedRecurringIssues();

    for (const rule of rules) {
      try {
        const outcome = await processRule(rule, now);
        if (outcome === "created") result.processed += 1;
        if (outcome === "refused") result.failed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue failed", {
          recurringIssueId: rule.id,
          orgId: rule.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function processRule(rule: RecurringIssue, now: Date): Promise<RuleOutcome> {
  const occurrence = latestOccurrence(rule, now);
  if (occurrence === null) return "skipped";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "skipped";
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) {
    logger.warn("recurring issue points at a missing project", {
      recurringIssueId: rule.id,
      projectId: rule.projectId,
    });
    return "refused";
  }
  // Left untouched: once the project is restored the next run files the
  // then-latest occurrence.
  if (isArchived(project)) return "skipped";

  // The issue is filed as the rule's creator, with their current role.
  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator !== null && creator.status === "active"
      ? { userId: creator.userId, orgId: rule.orgId, role: creator.role }
      : null;

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    logger.info("recurring issue paused: its creator can no longer file issues", {
      recurringIssueId: rule.id,
      createdBy: rule.createdBy,
    });
    return "paused";
  }

  let issueId: string;
  try {
    const input = createIssueSchema.parse({
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId: await activeAssignee(rule),
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
    issueId = (await createIssue(actor, input)).id;
  } catch (error) {
    // Refused (quota, validation …): leave the rule exactly as it was so a
    // later run tries again.
    logger.warn("recurring issue creation refused", {
      recurringIssueId: rule.id,
      occurrence,
      reason: error instanceof Error ? error.message : String(error),
    });
    return "refused";
  }

  await recurringIssueRepo.setLastOccurrence(rule.orgId, rule.id, occurrence);
  logger.debug("recurring issue filed", {
    recurringIssueId: rule.id,
    occurrence,
    issueId,
  });
  return "created";
}

/** The rule's assignee while they are still an active member, else nobody. */
async function activeAssignee(rule: RecurringIssue): Promise<UserId | null> {
  if (rule.assigneeId === null) return null;
  const member = await memberRepo.findMember(rule.orgId, rule.assigneeId);
  return member !== null && member.status === "active" ? member.userId : null;
}

